import { format, isThisYear, isToday, isYesterday } from "date-fns";
import type { ThreadAttachment, ThreadMessage } from "@aybsig/messenger";
import { toDate } from "./messenger.format";

export type ThreadRenderItem =
  | { kind: "title"; key: string; label: string }
  | {
      kind: "message";
      key: string;
      message: ThreadMessage;
      variant: "text" | "image" | "audio";
      attachment: ThreadAttachment | null;
      first: boolean;
      last: boolean;
      tail: boolean;
      showFooter: boolean;
    };

export function messageBodyToText(body: string): string {
  if (!body) return "";
  return body
    .replace(/<br\s*\/?>/gi, "\n")
    .replace(/<\/(p|div|li)>/gi, "\n")
    .replace(/<[^>]+>/g, "")
    .replace(/&nbsp;/gi, " ")
    .replace(/&amp;/gi, "&")
    .replace(/&lt;/gi, "<")
    .replace(/&gt;/gi, ">")
    .replace(/\n{3,}/g, "\n\n")
    .trim();
}

const IMAGE_EXT = /\.(jpe?g|png|gif|webp|bmp|heic|heif|svg)$/i;
const AUDIO_EXT = /\.(webm|ogg|oga|m4a|mp3|wav|opus|aac|amr|3gp)$/i;

export function isImageAttachment(attachment: ThreadAttachment): boolean {
  return attachment.mimetype.startsWith("image/") || IMAGE_EXT.test(attachment.name);
}

export function isAudioAttachment(attachment: ThreadAttachment): boolean {
  return attachment.mimetype.startsWith("audio/") || AUDIO_EXT.test(attachment.name);
}

function dayKey(value: string | null): string {
  if (!value) return "unknown";
  const date = toDate(value);
  if (Number.isNaN(date.getTime())) return "unknown";
  return format(date, "yyyy-MM-dd");
}

export function formatMessageTime(value: string | null): string {
  if (!value) return "";
  const date = toDate(value);
  if (Number.isNaN(date.getTime())) return "";
  return format(date, "HH:mm");
}

export function formatDayTitle(value: string | null): string {
  if (!value) return "";
  const date = toDate(value);
  if (Number.isNaN(date.getTime())) return "";
  if (isToday(date)) return "Today";
  if (isYesterday(date)) return "Yesterday";
  if (isThisYear(date)) return format(date, "EEEE, d MMM");
  return format(date, "d MMM yyyy");
}

interface Leaf {
  message: ThreadMessage;
  variant: "text" | "image" | "audio";
  attachment: ThreadAttachment | null;
}

function toLeaves(message: ThreadMessage): Leaf[] {
  const leaves: Leaf[] = [];

  for (const attachment of message.attachments) {
    if (isImageAttachment(attachment)) {
      leaves.push({ message, variant: "image", attachment });
    } else if (isAudioAttachment(attachment)) {
      leaves.push({ message, variant: "audio", attachment });
    }
  }

  if (messageBodyToText(message.body)) {
    leaves.push({ message, variant: "text", attachment: null });
  }

  if (leaves.length === 0) {
    leaves.push({ message, variant: "text", attachment: null });
  }

  return leaves;
}

function resolveIsMine(message: ThreadMessage, partnerId: number | null): boolean {
  if (partnerId !== null) return message.authorId === partnerId;
  return message.isMine;
}

function groupKey(message: ThreadMessage, partnerId: number | null): string {
  const mine = resolveIsMine(message, partnerId);
  return `${mine ? "me" : "them"}|${message.authorId ?? "?"}|${dayKey(message.date)}`;
}

export function buildThreadItems(
  messages: readonly ThreadMessage[],
  currentPartnerId: number | null = null,
): ThreadRenderItem[] {
  const leaves = messages.flatMap(toLeaves);
  const items: ThreadRenderItem[] = [];
  let previousDay: string | null = null;

  leaves.forEach((leaf, index) => {
    const day = dayKey(leaf.message.date);
    if (day !== previousDay) {
      items.push({
        kind: "title",
        key: `title-${day}-${leaf.message.id}`,
        label: formatDayTitle(leaf.message.date),
      });
      previousDay = day;
    }

    const prev = leaves[index - 1];
    const next = leaves[index + 1];
    const key = groupKey(leaf.message, currentPartnerId);
    const first =
      !prev ||
      groupKey(prev.message, currentPartnerId) !== key ||
      dayKey(prev.message.date) !== day;
    const last = !next || groupKey(next.message, currentPartnerId) !== key;

    const isMine = resolveIsMine(leaf.message, currentPartnerId);
    const message = isMine === leaf.message.isMine ? leaf.message : { ...leaf.message, isMine };

    const base = message.tempId ?? `msg-${message.id}`;
    const suffix =
      leaf.variant === "text" ? "text" : `${leaf.variant}-${leaf.attachment?.id ?? index}`;

    items.push({
      kind: "message",
      key: `${base}-${suffix}`,
      message,
      variant: leaf.variant,
      attachment: leaf.attachment,
      first,
      last,
      tail: last,
      showFooter: last,
    });
  });

  return items;
}
